"""Macroéconomie et banques centrales : indicateurs, politique monétaire, cycle."""
from __future__ import annotations

from patrick.knowledge.dictionary import d

T = "macro"
TERMS = [
    d(T, "pib", "PIB (produit intérieur brut)", "GDP (gross domestic product)", 1,
      "Valeur de tous les biens et services produits dans un pays sur une période (trimestre, année). Sa variation, la croissance, résume la santé de l'économie. Il est publié avec retard, estimé trois fois, puis révisé pendant des années.",
      "Value of all goods and services produced in a country over a period (quarter, year). Its change, growth, summarises the economy's health. It is published with a lag, estimated three times, then revised for years.",
      see="croissance_reelle_nominale recession revision_donnees", alias="GDP"),
    d(T, "croissance_reelle_nominale", "Croissance réelle et nominale", "Real and nominal growth", 1,
      "La croissance nominale est celle du PIB en euros courants ; la réelle en retire l'inflation. Une économie dont le PIB nominal monte de 5 % avec 3 % d'inflation croît en réalité d'environ 2 %.",
      "Nominal growth is that of GDP in current euros; real growth strips out inflation. An economy whose nominal GDP rises 5% with 3% inflation really grows about 2%.",
      see="pib inflation"),
    d(T, "ipc", "Indice des prix à la consommation (IPC / CPI)", "Consumer price index (CPI)", 1,
      "Coût d'un panier représentatif de biens et services acheté par les ménages ; sa variation sur un an est le taux d'inflation le plus cité. L'inflation « sous-jacente » (core) exclut l'alimentation et l'énergie, plus volatiles.",
      "Cost of a representative basket of goods and services bought by households; its one-year change is the most-quoted inflation rate. 'Core' inflation excludes the more volatile food and energy.",
      see="inflation pce_core", alias="CPI; inflation"),
    d(T, "pce_core", "Déflateur PCE et inflation sous-jacente", "PCE deflator and core inflation", 2,
      "Mesure d'inflation préférée de la Réserve fédérale (dépenses de consommation des ménages), au panier et aux pondérations plus souples que l'IPC. Sa version « core » sert de cible implicite autour de 2 %.",
      "The Federal Reserve's preferred inflation gauge (personal consumption expenditures), with a more flexible basket and weights than CPI. Its 'core' version serves as the implicit 2% target.",
      see="ipc fed"),
    d(T, "deflation", "Déflation et désinflation", "Deflation and disinflation", 2,
      "La désinflation est un ralentissement de la hausse des prix ; la déflation, une baisse générale des prix, dangereuse car elle pousse à différer les achats et alourdit le poids réel des dettes.",
      "Disinflation is a slowdown in the rise of prices; deflation is a general fall in prices, dangerous because it encourages delaying purchases and raises the real burden of debt.",
      see="inflation recession"),
    d(T, "stagflation", "Stagflation", "Stagflation", 2,
      "Combinaison d'une croissance faible ou négative, d'un chômage élevé et d'une inflation forte (années 1970). Elle met en difficulté la banque centrale : monter les taux contre l'inflation aggrave le ralentissement.",
      "Combination of weak or negative growth, high unemployment and high inflation (1970s). It puts the central bank in a bind: raising rates against inflation worsens the slowdown.",
      see="inflation politique_monetaire"),
    d(T, "chomage_nfp", "Chômage et créations d'emplois (NFP)", "Unemployment and payrolls (NFP)", 1,
      "Le taux de chômage mesure la part des actifs sans emploi ; les créations d'emplois non agricoles (NFP) aux États-Unis, publiées le premier vendredi du mois, sont l'un des chiffres les plus suivis des marchés.",
      "The unemployment rate measures the share of the labour force without a job; US non-farm payrolls (NFP), released the first Friday of the month, are among the most-watched market figures.",
      see="cycle_economique evenement_macro", alias="NFP; non-farm payrolls"),
    d(T, "pmi_ism", "PMI et ISM (enquêtes d'activité)", "PMI and ISM (activity surveys)", 2,
      "Indices issus d'enquêtes auprès des directeurs d'achat : au-dessus de 50, l'activité progresse ; en dessous, elle recule. Publiés dès le début du mois suivant, ils devancent les statistiques officielles, d'où leur poids sur les marchés.",
      "Indices from purchasing-manager surveys: above 50 activity is expanding; below, contracting. Released at the start of the following month, they lead official statistics, hence their weight on markets.",
      see="indicateurs_avances cycle_economique", alias="PMI; ISM"),
    d(T, "indicateurs_avances", "Indicateurs avancés, coïncidents et retardés", "Leading, coincident and lagging indicators", 2,
      "Les avancés (commandes, courbe des taux, confiance) se retournent avant l'économie ; les coïncidents (production, revenus) avec elle ; les retardés (chômage, crédits) après. On les utilise pour situer le cycle.",
      "Leading indicators (orders, yield curve, confidence) turn before the economy; coincident ones (output, income) with it; lagging ones (unemployment, credit) after. They are used to locate the cycle.",
      see="cycle_economique pmi_ism courbe_des_taux"),
    d(T, "politique_monetaire", "Politique monétaire", "Monetary policy", 1,
      "Action de la banque centrale sur les taux et la quantité de monnaie pour viser la stabilité des prix et soutenir l'emploi. Elle agit avec un délai de plusieurs trimestres sur l'économie, beaucoup plus vite sur les marchés.",
      "Central-bank action on rates and the money supply to target price stability and support employment. It acts on the economy with a lag of several quarters, far faster on markets.",
      see="taux_directeur fed bce"),
    d(T, "taux_directeur", "Taux directeur", "Policy rate", 1,
      "Taux fixé par la banque centrale (taux des fonds fédéraux de la Fed, taux de dépôt de la BCE) auquel les banques se prêtent ou placent la liquidité. Il ancre les taux courts et influence toute la courbe.",
      "Rate set by the central bank (the Fed's federal funds rate, the ECB's deposit rate) at which banks lend or park liquidity. It anchors short rates and influences the whole curve.",
      see="courbe_des_taux politique_monetaire taux_sans_risque", alias="taux de la banque centrale"),
    d(T, "fed", "Réserve fédérale (Fed) et FOMC", "Federal Reserve (Fed) and FOMC", 1,
      "Banque centrale des États-Unis. Son comité de politique monétaire (FOMC) se réunit huit fois par an, décide du taux directeur et publie un communiqué, des projections et un procès-verbal que les marchés épluchent.",
      "The US central bank. Its monetary policy committee (FOMC) meets eight times a year, sets the policy rate and publishes a statement, projections and minutes that markets scrutinise.",
      see="taux_directeur dot_plot forward_guidance", alias="FOMC"),
    d(T, "bce", "Banque centrale européenne (BCE)", "European Central Bank (ECB)", 1,
      "Banque centrale de la zone euro. Son objectif principal est une inflation proche de 2 % à moyen terme. Ses décisions (taux de dépôt, programmes d'achats d'actifs) sont annoncées lors du conseil des gouverneurs.",
      "Central bank of the euro area. Its primary goal is inflation near 2% over the medium term. Its decisions (deposit rate, asset-purchase programmes) are announced at the Governing Council.",
      see="taux_directeur politique_monetaire", alias="ECB"),
    d(T, "qe_qt", "Assouplissement et resserrement quantitatif (QE / QT)", "Quantitative easing and tightening (QE / QT)", 2,
      "Avec le QE, la banque centrale achète des obligations pour faire baisser les taux longs et injecter de la liquidité quand le taux directeur est déjà près de zéro. Le QT est l'inverse : elle laisse son bilan se réduire.",
      "With QE the central bank buys bonds to lower long rates and inject liquidity when the policy rate is already near zero. QT is the reverse: it lets its balance sheet shrink.",
      see="politique_monetaire courbe_des_taux", alias="QE; QT"),
    d(T, "forward_guidance", "Orientation prospective (forward guidance)", "Forward guidance", 2,
      "Communication de la banque centrale sur la trajectoire probable de ses taux. Elle agit sur les taux longs avant toute décision : une surprise de ton compte souvent plus qu'une décision attendue.",
      "Central-bank communication about the likely path of its rates. It moves long rates before any decision: a surprise in tone often matters more than an expected decision.",
      see="fed bce hawkish_dovish_macro"),
    d(T, "hawkish_dovish_macro", "Ton « hawkish » et « dovish »", "Hawkish and dovish tone", 2,
      "Un discours « hawkish » (faucon) privilégie la lutte contre l'inflation et annonce des taux plus hauts ; un discours « dovish » (colombe) privilégie la croissance et annonce des taux plus bas. On le mesure aussi sur les textes.",
      "A 'hawkish' message favours fighting inflation and signals higher rates; a 'dovish' one favours growth and signals lower rates. It can also be measured on text.",
      see="news_tone forward_guidance"),
    d(T, "dot_plot", "Graphique des points (dot plot)", "Dot plot", 3,
      "Graphique publié par la Fed où chaque membre du FOMC place sa prévision du taux directeur à fin d'année. La médiane des points sert de repère aux marchés sur le rythme futur des taux.",
      "Chart published by the Fed where each FOMC member plots their year-end policy-rate forecast. The median dot serves as a market benchmark for the future pace of rates.",
      see="fed forward_guidance"),
    d(T, "taux_neutre", "Taux neutre", "Neutral rate", 3,
      "Taux d'intérêt réel qui ne stimule ni ne freine l'économie quand elle est au plein emploi avec une inflation à la cible. Inobservable, il est estimé par des modèles ; il détermine si la politique monétaire est restrictive ou accommodante.",
      "Real interest rate that neither stimulates nor restrains the economy at full employment with inflation on target. Unobservable, it is estimated by models; it determines whether policy is restrictive or accommodative.",
      see="taux_directeur regle_de_taylor"),
    d(T, "regle_de_taylor", "Règle de Taylor", "Taylor rule", 3,
      "Formule qui relie le taux directeur à l'écart d'inflation par rapport à la cible et à l'écart de production : taux = taux neutre + inflation + 0,5 × (inflation − cible) + 0,5 × écart de production. Repère pour juger si la banque centrale est en retard ou en avance.",
      "Formula tying the policy rate to the inflation gap from target and the output gap: rate = neutral rate + inflation + 0.5 × (inflation − target) + 0.5 × output gap. A benchmark to judge whether the central bank is behind or ahead.",
      formula=r"i = r^* + \pi + 0{,}5(\pi - \pi^*) + 0{,}5\, y", see="taux_neutre taux_directeur"),
    d(T, "courbe_de_phillips", "Courbe de Phillips", "Phillips curve", 3,
      "Relation observée entre chômage et inflation : quand le chômage est bas, les salaires et les prix tendent à accélérer. Son pente a varié dans le temps et les anticipations d'inflation y jouent un grand rôle.",
      "Observed relation between unemployment and inflation: when unemployment is low, wages and prices tend to accelerate. Its slope has varied over time and inflation expectations play a large part.",
      see="inflation chomage_nfp"),
    d(T, "balance_commerciale", "Balance commerciale et balance des paiements", "Trade balance and balance of payments", 2,
      "La balance commerciale est la différence entre exportations et importations de biens ; la balance des paiements y ajoute services, revenus et capitaux. Un déficit durable se finance par des capitaux étrangers et pèse parfois sur la devise.",
      "The trade balance is exports minus imports of goods; the balance of payments adds services, income and capital flows. A lasting deficit is financed by foreign capital and sometimes weighs on the currency.",
      see="devise_change"),
    d(T, "dette_deficit_public", "Déficit et dette publics", "Government deficit and debt", 2,
      "Le déficit est l'écart annuel entre dépenses et recettes de l'État ; la dette cumule les déficits passés. Rapportée au PIB, elle mesure la soutenabilité ; l'écart de taux avec l'Allemagne (spread) mesure la défiance sur un État de la zone euro.",
      "The deficit is the yearly gap between government spending and revenue; debt accumulates past deficits. As a share of GDP it measures sustainability; the spread against Germany measures distrust of a euro-area state.",
      see="spread_de_credit obligation"),
    d(T, "politique_budgetaire", "Politique budgétaire", "Fiscal policy", 2,
      "Usage des dépenses et des impôts de l'État pour influencer l'économie, par opposition à la politique monétaire de la banque centrale. Un plan de relance soutient la croissance mais creuse le déficit et peut pousser les taux longs.",
      "Use of government spending and taxes to influence the economy, as opposed to the central bank's monetary policy. A stimulus plan supports growth but widens the deficit and may push long rates up.",
      see="dette_deficit_public politique_monetaire"),
    d(T, "ppa_taux_reel_change", "Parité de pouvoir d'achat et taux de change réel", "Purchasing-power parity and real exchange rate", 3,
      "La PPA dit qu'à long terme un même panier doit coûter pareil partout une fois converti : le taux de change doit compenser l'écart d'inflation. Le taux de change réel mesure l'écart à cette parité et sert à repérer une devise chère ou bon marché.",
      "PPP says that in the long run the same basket should cost the same everywhere once converted: the exchange rate should offset the inflation gap. The real exchange rate measures the deviation from that parity and flags an expensive or cheap currency.",
      see="devise_change inflation", alias="PPA; PPP"),
    d(T, "spread_taux_pays", "Spread souverain", "Sovereign spread", 2,
      "Écart de rendement entre l'obligation d'un État et celle d'une référence jugée sans risque (le Bund allemand en Europe, le Treasury aux États-Unis). Il s'élargit quand le risque de défaut, de sortie de la monnaie ou de liquidité augmente.",
      "Yield gap between a government's bond and a benchmark judged risk-free (the German Bund in Europe, the Treasury in the US). It widens when default, redenomination or liquidity risk rises.",
      see="spread_de_credit dette_deficit_public"),
    d(T, "evenement_macro", "Événement macroéconomique", "Macroeconomic event", 2,
      "Publication ou décision datée qui peut faire bouger les marchés : inflation, emploi, PIB, réunion de banque centrale. Les marchés réagissent à la surprise (écart entre le chiffre publié et le consensus), pas au chiffre lui-même.",
      "Dated release or decision that can move markets: inflation, jobs, GDP, central-bank meeting. Markets react to the surprise (gap between the published figure and consensus), not the figure itself.",
      see="consensus_analystes surprise_resultats"),
    d(T, "cycle_credit", "Cycle du crédit", "Credit cycle", 3,
      "Alternance de phases où le crédit est abondant et bon marché (écarts serrés, défauts rares) et de phases de resserrement (écarts larges, défauts en hausse). Les excès de la première préparent souvent la seconde.",
      "Alternation of phases where credit is plentiful and cheap (tight spreads, few defaults) and tightening phases (wide spreads, rising defaults). Excesses in the first often prepare the second.",
      see="spread_de_credit cycle_economique"),
    d(T, "revision_croissance_potentielle", "Croissance potentielle et écart de production", "Potential growth and output gap", 3,
      "La croissance potentielle est le rythme soutenable sans accélérer l'inflation ; l'écart de production est la différence entre le PIB réel et son niveau potentiel. Estimé après coup, il est très révisé.",
      "Potential growth is the sustainable pace without accelerating inflation; the output gap is the difference between real GDP and its potential level. Estimated after the fact, it is heavily revised.",
      see="pib regle_de_taylor"),
    d(T, "monnaie_masse", "Masse monétaire et crédit", "Money supply and credit", 3,
      "La masse monétaire (M1, M2, M3) mesure la monnaie en circulation et les dépôts. Sa croissance, avec celle du crédit bancaire, renseigne sur la liquidité de l'économie et, avec délai, sur l'inflation et les actifs.",
      "The money supply (M1, M2, M3) measures money in circulation and deposits. Its growth, with that of bank credit, tells about economy-wide liquidity and, with a lag, about inflation and asset prices.",
      see="qe_qt inflation"),
    d(T, "choc_offre_demande", "Choc d'offre et choc de demande", "Supply and demand shocks", 3,
      "Un choc de demande (confiance, relance) déplace production et prix dans le même sens ; un choc d'offre (pétrole, chaîne logistique) les déplace en sens opposé. La réponse des marchés et de la banque centrale diffère selon le cas.",
      "A demand shock (confidence, stimulus) moves output and prices the same way; a supply shock (oil, supply chain) moves them opposite ways. Market and central-bank responses differ accordingly.",
      see="stagflation politique_monetaire"),
]
